'use strict';
(() => {
 const $ = id => document.getElementById(id);
 const clone = x => JSON.parse(JSON.stringify(x));
 const finite = x => typeof x === 'number' && Number.isFinite(x);
 const num = id => Number($(id).value);
 const money = x => finite(x) ? new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Math.abs(x)<.5?0:x) : '—';
 const signed = x => finite(x) ? (x>.5?'+':'')+money(x) : '—';
 const pct = x => finite(x) ? (x*100).toFixed(2)+'%' : '—';
 const rate = x => finite(x) ? x.toLocaleString('en-US',{maximumFractionDigits:3})+'%' : '—';
 const decimal = x => finite(x) ? x.toLocaleString('en-US',{maximumFractionDigits:3}) : '—';
 const labels = {A:'A · 指數 ETF',B:'B · 純多頭＋TLH',C:'C · 130/30 不收割',D:'D · 稅務感知 QP＋TLH'};
 const colors = {A:'#667b83',B:'#4779ab',C:'#bc8a4b',D:'#008579'};
 const controls = {cash:'initial_cash',start:'start_date',end:'end_date',benchmark:'benchmark',finance:'financing_pct',borrow:'borrow_pct',manager:'manager_pct',advisor:'advisor_pct','tax-st':'tax_st_pct','tax-lt':'tax_lt_pct',trade:'transaction_pct',rebate:'rebate_pct',rebalance:'rebalance_every_sessions',threshold:'harvest_threshold_pct',maintenance:'maintenance_equity_to_gross_pct'};
 let defaults,lastResult,busy=false,dirty=false,timer,seconds=0,metric='delta_D_A',selectedCost,activeGroup='demo',drafts={};
 function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=String(text);return n;}
 function add(parent,tag,className,text){const n=el(tag,className,text);parent.appendChild(n);return n;}
 function section(parent,title,description,chartNumber){const panel=add(parent,'section','panel report-section');const head=add(panel,'div','section-head');const left=add(head,'div');if(chartNumber)add(left,'span','chart-number',chartNumber);add(left,'h3','',title);if(description)add(left,'p','section-description',description);return {panel,head};}
 function details(parent,title,open=false){const d=add(parent,'details','details');d.open=open;add(d,'summary','',title);return d;}
 function table(parent,columns,rows){const wrap=add(parent,'div','table-scroll');const t=add(wrap,'table');const tr=add(add(t,'thead'),'tr');columns.forEach(([name])=>add(tr,'th','',name));const body=add(t,'tbody');for(const r of rows){const row=add(body,'tr',r.strategy==='D'?'emphasis':'');for(const[,key,format]of columns){const v=typeof key==='function'?key(r):r[key];add(row,'td','',format?format(v):v===undefined||v===null?'—':String(v));}}return t;}
 function sourceGroup(){return $('data-source').value==='demo'?'demo':'observed';}
 function baseConfig(){return defaults[sourceGroup()==='demo'?'demo_config':'observed_config'];}
 function positionsText(c){return(c.positions||[]).map(p=>[p.ticker,p.side,p.weight,c.substitutes?.[p.ticker]?.ticker||''].join(',')).join('\n');}
 function draft(){return{start:$('start').value,end:$('end').value,benchmark:$('benchmark').value,positions:$('positions').value,year:$('gain-year').value};}
 function applyGroup(c,d){$('start').value=d?.start||c.start_date;$('end').value=d?.end||c.end_date;$('benchmark').value=d?.benchmark||c.benchmark||'SPY';$('positions').value=d?.positions||positionsText(c);$('gain-year').value=d?.year||(c.outside_gain_events||[])[0]?.year||c.event_year||Number(c.start_date.slice(0,4));}
 function sourceNote(){const source=$('data-source').value;$('upload-row').hidden=source!=='uploaded';$('source-note').textContent={demo:'合成價格，僅供操作與模型檢查。不能視為市場證據、經理人績效或未來報酬。',live:'下載歷史價格、股息與拆股；最佳化需研究開始前的估計窗口。缺資料會停止，不補造價格。',uploaded:'上傳原始行情 JSON，須包含開始日前的歷史窗口與來源 metadata。檔案本身不代表已獨立驗證。',local_cache:'使用本機凍結快照；開始日期需保留足夠的過去行情作風險估計。快照不存在時請改用其他來源。'}[source];}
 function rates(value,label){const a=value.split(/[,，]/).map(x=>x.trim());if(!a.length||a.length>3||a.some(x=>x===''))throw Error(label+'需填 1–3 個數字，使用逗號分隔。');const out=a.map(Number);if(out.some(x=>!Number.isFinite(x)||x<0||x>30))throw Error(label+'須介於 0–30%。');if(new Set(out).size!==out.length)throw Error(label+'不可重複。');return out.sort((a,b)=>a-b);}
 function optionalFields(){const sens=$('sensitivity-enabled').checked,mc=$('mc-enabled').checked;$('sensitivity-fields').hidden=!sens;$('mc-fields').hidden=!mc;for(const id of ['finance-rates','borrow-rates'])$(id).disabled=busy||!sens;for(const id of ['paths','seed'])$(id).disabled=busy||!mc;try{const n=rates($('finance-rates').value,'融資測試點').length,m=rates($('borrow-rates').value,'借券測試點').length;$('grid-note').textContent=n+' × '+m+'＝'+n*m+' 個配對成本情境。每格重跑四策略與 QP，會增加計算時間。';}catch(_){$('grid-note').textContent='每軸最多三個不同測試點，最多 9 格。';}}
 function markDirty(){if(busy)return;optionalFields();if(lastResult){dirty=true;$('stale').hidden=false;$('output').classList.add('old-result');$('export').disabled=true;$('print').disabled=true;}$('status').textContent='條件已修改。請重新執行以更新四策略與研究結果。';}
 function reset(){if(!defaults||busy)return;$('data-source').value='demo';activeGroup='demo';drafts={};const c=defaults.demo_config;for(const[id,key]of Object.entries(controls))if(c[key]!==undefined)$(id).value=c[key];applyGroup(c);const gain=(c.outside_gain_events||[])[0];$('gain').value=gain?.amount||0;$('gain-character').value=gain?.character||'st';const options=defaults.defaults||{};const o=options.optimization||defaults.optimization||{};for(const[id,key,fallback]of [['risk-aversion','risk_aversion',50],['lookback','lookback',126],['long-cap','long_cap_pct',60],['short-cap','short_cap_pct',20]])$(id).value=o[key]??fallback;const s=options.sensitivities||defaults.sensitivities||{};$('sensitivity-enabled').checked=s.enabled!==false;$('finance-rates').value=(s.financing_rates||[3,5,7]).join(', ');$('borrow-rates').value=(s.borrow_rates||[0,1,3]).join(', ');$('mc-enabled').checked=false;$('paths').value=5;$('seed').value=4511;$('replacement-reviewed').checked=true;$('form-error').hidden=true;sourceNote();optionalFields();markDirty();if(!lastResult)$('status').textContent='示例已準備。可先關閉額外研究快速執行四策略，再加入成本網格或情境路徑。';}
 function readPositions(){const rows=$('positions').value.trim().split(/\n/).filter(x=>x.trim());if(rows.length<2||rows.length>20)throw Error('請填 2–20 檔原股，並保留多頭與空頭。');const ps=[],subs={},names=[];for(const[line,index]of rows.map((line,i)=>[line,i])){const p=line.split(',').map(x=>x.trim());if(p.length!==4)throw Error('第 '+(index+1)+' 行需四欄：股票,方向,權重,替代股票。');const ticker=p[0].toUpperCase(),side=p[1].toLowerCase(),replacement=p[3].toUpperCase(),weight=Number(p[2]);if(!/^[A-Z][A-Z0-9-]{0,14}$/.test(ticker)||!/^[A-Z][A-Z0-9-]{0,14}$/.test(replacement)||!['long','short'].includes(side)||!Number.isFinite(weight)||weight<=0)throw Error('第 '+(index+1)+' 行代號、方向或權重不正確。');ps.push({ticker,side,weight});subs[ticker]={ticker:replacement,reviewed_not_substantially_identical:true,review_basis:'Explicit research assumption; not legal approval.'};names.push(ticker,replacement);}if(new Set(names).size!==names.length)throw Error('此批次引擎要求原股與替代股票全部不同。');const nl=ps.filter(p=>p.side==='long').length,ns=ps.length-nl;if(!nl||!ns)throw Error('130/30 候選組合需同時有多頭與空頭。');if(nl*num('long-cap')<130-1e-8||ns*num('short-cap')<30-1e-8)throw Error('單股上限與檔數無法達到 130/30，請增加股票或提高上限。');return{positions:ps,substitutes:subs};}
 async function payload(){const c=clone(baseConfig());for(const[id,key]of Object.entries(controls))c[key]=['start','end','benchmark'].includes(id)?$(id).value:num(id);c.benchmark=c.benchmark.trim().toUpperCase();if(c.end_date<=c.start_date)throw Error('最後日期須晚於開始日期。');Object.assign(c,readPositions(),{long_exposure_pct:130,short_exposure_pct:30,ordinary_tax_pct:num('tax-st'),dividend_tax_pct:num('tax-lt')});const amount=num('gain'),year=num('gain-year');if(amount>0&&(!Number.isInteger(year)||year<Number(c.start_date.slice(0,4))||year>Number(c.end_date.slice(0,4))))throw Error('正的外部收益需指定研究期間內的整數年度。');c.outside_gain_events=amount>0?[{year,amount,character:$('gain-character').value}]:[];if(!$('replacement-reviewed').checked)throw Error('請先確認所列替代股票假設。');const s=$('sensitivity-enabled').checked;const request={config:c,data_source:$('data-source').value,optimization:{risk_aversion:num('risk-aversion'),lookback:num('lookback'),long_cap_pct:num('long-cap'),short_cap_pct:num('short-cap')},sensitivities:{enabled:s,financing_rates:s?rates($('finance-rates').value,'融資測試點'):[c.financing_pct],borrow_rates:s?rates($('borrow-rates').value,'借券測試點'):[c.borrow_pct]},monte_carlo:{enabled:$('mc-enabled').checked,paths:$('mc-enabled').checked?num('paths'):5,seed:$('mc-enabled').checked?num('seed'):4511}};if(request.data_source==='uploaded'){const f=$('history-file').files[0];if(!f)throw Error('請選擇原始行情 JSON。');if(f.size>4500000)throw Error('行情 JSON 請小於 4.5 MB。');try{request.history=JSON.parse(await f.text());}catch(_){throw Error('無法讀取行情 JSON。');}}return request;}
 function svg(parent,name,attrs,text){const n=document.createElementNS('http://www.w3.org/2000/svg',name);for(const[k,v]of Object.entries(attrs||{}))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=String(text);parent.appendChild(n);return n;}
 function compact(x){const a=Math.abs(x);return(a>=1e6?(x/1e6).toFixed(2)+'M':a>=1000?(x/1000).toFixed(0)+'k':x.toFixed(0));}
 function lineChart(parent,series,title,{zero=false}={}){series=series.filter(s=>s.points.some(p=>finite(p.value)));if(!series.length){add(parent,'p','warning','此結果未提供可繪製的逐日欄位；不以估算值補造曲線。');return;}const points=series.flatMap(s=>s.points.filter(p=>finite(p.value))),times=points.map(p=>Date.parse(p.date)),values=points.map(p=>p.value);let min=Math.min(...values),max=Math.max(...values);if(zero){min=Math.min(0,min);max=Math.max(0,max);}const pad=Math.max((max-min)*.09,Math.max(Math.abs(max),1)*.03);min=(zero&&values.every(v=>v>=0))?0:min-pad;max+=pad;const lo=Math.min(...times),hi=Math.max(...times),left=82,right=870,top=22,bottom=232,x=v=>left+(Date.parse(v)-lo)/(hi-lo||1)*(right-left),y=v=>bottom-(v-min)/(max-min||1)*(bottom-top);const plot=svg(parent,'svg',{viewBox:'0 0 900 272',class:'chart',role:'img','aria-label':title});svg(plot,'title',{},title);for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;svg(plot,'line',{x1:left,x2:right,y1:y(v),y2:y(v),class:'chart-grid'});svg(plot,'text',{x:left-11,y:y(v)+4,'text-anchor':'end'},'$'+compact(v));}if(min<=0&&max>=0)svg(plot,'line',{x1:left,x2:right,y1:y(0),y2:y(0),class:'zero-line'});for(const t of [lo,(lo+hi)/2,hi])svg(plot,'text',{x:left+(t-lo)/(hi-lo||1)*(right-left),y:255,'text-anchor':'middle'},new Date(t).toISOString().slice(0,7));for(const s of series){let path='',active=false;for(const p of s.points){if(!finite(p.value)){active=false;continue;}path+=(active?'L':'M')+x(p.date).toFixed(2)+' '+y(p.value).toFixed(2)+' ';active=true;}svg(plot,'path',{d:path,fill:'none',stroke:s.color||colors[s.key]||colors.D,'stroke-width':s.key==='D'?2.7:1.9});}const legend=add(parent,'div','legend');for(const s of series){const item=add(legend,'span');const swatch=add(item,'i');swatch.style.backgroundColor=s.color||colors[s.key]||colors.D;item.appendChild(document.createTextNode(s.name||labels[s.key]));}}
 function dailySeries(result,key,field){return{key,name:labels[key],points:(result.strategies?.[key]?.daily||[]).map(d=>({date:d.date,value:d[field]}))};}
 function differenceSeries(result,strategy,baseline,field,name){const base=new Map((result.strategies?.[baseline]?.daily||[]).map(d=>[d.date,d[field]]));return{key:strategy,name,points:(result.strategies?.[strategy]?.daily||[]).map(d=>({date:d.date,value:finite(base.get(d.date))&&finite(d[field])?base.get(d.date)-d[field]:null}))};}
 function comparisonRows(result){return(result.comparison||[]).map(r=>({...r,label:labels[r.strategy]||r.label}));}
 function renderTop(out,result){const kind=result.data_kind;const p=add(out,'div','provenance '+(kind==='observed'?'observed':kind==='synthetic'?'':'unverified'));add(p,'strong','',kind==='synthetic'?'合成示例結果 · 不代表歷史投資績效':kind==='observed'?'歷史行情 · 假設交易與客戶條件':'使用者提供資料 · 來源尚待驗證');add(p,'p','',result.data_label||'請核對匯出的行情來源與假設。');if(kind==='synthetic')add(p,'p','','人造路徑用於操作與模型驗證，不能作為市場證據或未來報酬預測。');const c=result.request?.config||{},event=(c.outside_gain_events||[])[0],caseText='初始 '+money(c.initial_cash)+'｜'+c.start_date+' 至 '+c.end_date+'｜外部收益 '+(event?money(event.amount)+'（'+event.year+'，'+event.character.toUpperCase()+'）':'$0（無事件）')+'｜基準 '+(c.benchmark||'SPY')+'｜期限末全數清倉';add(out,'p','case-line',caseText);add(out,'p','print-case','P107 Tax-Aware Research Lab\n'+caseText+'\n資料：'+(result.data_label||kind)+'\n融資 '+rate(c.financing_pct)+'／借券 '+rate(c.borrow_pct)+'／Core 管理 '+rate(c.manager_pct)+'／ST '+rate(c.tax_st_pct)+'／LT '+rate(c.tax_lt_pct)+'\n最佳化 '+JSON.stringify(result.request?.optimization||{})+'\nRun '+result.run_id);const rows=comparisonRows(result),d=rows.find(r=>r.strategy==='D');const cards=add(out,'div','summary-cards');const best=rows.filter(r=>finite(r.terminal_wealth)).sort((a,b)=>b.terminal_wealth-a.terminal_wealth)[0];for(const[title,value,note,numeric]of [['D 相對 A 的期末財富差',d?.delta_vs_A,'包含組合配置、槓桿、交易、成本與稅務。',true],['D 相對 C 的期末財富差',d?.delta_vs_C,'同方向候選集，但最佳化權重與交易也改變；非純節稅。',true],['本次路徑的最高期末財富',best?.strategy||'—','僅是這份路徑與條件的比較，未建立通用客戶適合度。',false]]){const card=add(cards,'article','panel summary-card');add(card,'p','card-label',title);add(card,'div','card-value '+(numeric&&finite(value)?value>=0?'positive':'negative':''),numeric?signed(value):best?labels[value]:value);add(card,'p','',note);}const {panel}=section(out,'四策略的期末結果','所有財富已納入各自模型稅款與成本；不要再將稅額差加回財富。B 是選定股票 basket，尚未代表完整商業化指數追蹤產品。');table(panel,[['策略','label'],['期末稅後財富','terminal_wealth',money],['相對 A','delta_vs_A',signed],['完整模型稅款','total_taxes',money],['融資及費用','total_costs',money],['規則收割損失','harvested_losses',money],['ST 結轉','carry_st',money],['LT 結轉','carry_lt',money]],rows);}
 function renderCharts(out,r){let s=section(out,'稅後帳面財富，直到完整清倉','期間內是已扣當期已付稅款與成本的帳面財富，仍可能有未付退出稅；最後一點完成出售並結算模型稅款。包含相同外部現金流，曲線不是獨立投資報酬率。','CHART 01 · WEALTH');lineChart(s.panel,['A','B','C','D'].map(k=>dailySeries(r,k,'total_investor_wealth')),'四策略帳面財富與最終清倉財富');s=section(out,'規則觸發收割損失，與已付資本稅差','左圖只累計規則觸發的收割損失；QP 與再平衡的其他已實現損失另見年度及批次帳本。右圖是配對控制組已付資本稅減策略已付資本稅，仍受不同報酬與交易路徑影響。','CHART 02 · LOSSES & TAX CASH FLOWS');const split=add(s.panel,'div','chart-split'),loss=add(split,'div'),tax=add(split,'div');add(loss,'h4','','規則觸發收割損失（USD）');lineChart(loss,['B','D'].map(k=>dailySeries(r,k,'cumulative_harvested_losses')),'規則觸發收割損失',{zero:true});add(tax,'h4','','實際已付資本稅差（USD，可正可負）');lineChart(tax,[differenceSeries(r,'B','A','cumulative_capital_tax','A 已付稅 − B 已付稅'),differenceSeries(r,'D','C','cumulative_capital_tax','C 已付稅 − D 已付稅')],'配對已付資本稅差',{zero:true});add(s.panel,'p','axis-note','正稅額差表示該策略截至當日付較少資本稅；它不是已驗證的永久節稅或純稅務 alpha。');s=section(out,'正未實現收益的潛在稅額','以每筆正未實現收益及模型稅率估計，未抵損失、結轉或跨類別淨額。這是潛在負債代理值，不是精確應付稅款；清倉後歸零。','CHART 03 · EMBEDDED TAX');lineChart(s.panel,['A','B','C','D'].map(k=>dailySeries(r,k,'embedded_tax_liability_estimate')),'正未實現收益潛在稅額',{zero:true});}
 function costDetail(parent,row){parent.replaceChildren();if(!row)return;add(parent,'h4','','融資 '+rate(row.financing_pct)+' · 借券 '+rate(row.borrow_pct));if(row.status!=='completed'){add(parent,'p','warning','此格未完成，不能當作 0 或有效的策略劣勢。'+(row.error||''));return;}table(parent,[['A 財富','wealth_A',money],['B 財富','wealth_B',money],['C 財富','wealth_C',money],['D 財富','wealth_D',money],['D − A','delta_D_A',signed],['D − C','delta_D_C',signed]],[row]);}
 function renderSensitivity(out,r){const data=r.sensitivity||{},rows=data.rows||[];const {panel,head}=section(out,'成本改變後，D 的優勢是否翻轉？','相同股票、行情、初始資金及外部收益，逐格重跑策略。格數描述指定成本設定，不是未來勝率。','CHART 04 · COST SENSITIVITY');if(!rows.length){add(panel,'p','explain','本次未執行成本網格。勾選左側敏感度後重算，即可比較融資與借券費率。');return;}const control=add(head,'label','metric-control','顯示差額');const select=add(control,'select');select.id='sensitivity-metric';for(const[value,name]of [['delta_D_A','D 相對 A 指數'],['delta_D_C','D 相對 C 不收割']]){const o=add(select,'option','',name);o.value=value;}select.value=metric;const fs=[...new Set(rows.map(x=>x.financing_pct))].sort((a,b)=>a-b),bs=[...new Set(rows.map(x=>x.borrow_pct))].sort((a,b)=>a-b);const wrap=add(panel,'div','table-scroll'),t=add(wrap,'table','heatmap'),h=add(add(t,'thead'),'tr');add(h,'th','','借券 ↓／融資 →');fs.forEach(f=>add(h,'th','',rate(f)));const tbody=add(t,'tbody'),detail=el('div','cell-detail');if(!selectedCost)selectedCost=rows.find(x=>x.status==='completed')||rows[0];for(const b of bs){const tr=add(tbody,'tr');add(tr,'th','',rate(b));for(const f of fs){const row=rows.find(x=>x.financing_pct===f&&x.borrow_pct===b);const td=add(tr,'td');if(!row){add(td,'span','','未提供');continue;}const ok=row.status==='completed',value=row[metric];const button=add(td,'button','heat-cell '+(!ok?'failed':value<0?'negative':'positive')+(row===selectedCost?' selected':''),ok?signed(value):'未完成');button.type='button';button.setAttribute('aria-label','融資 '+rate(f)+'，借券 '+rate(b)+'，'+(ok?signed(value):'未完成'));button.addEventListener('click',()=>{selectedCost=row;t.querySelectorAll('.selected').forEach(n=>n.classList.remove('selected'));button.classList.add('selected');costDetail(detail,row);});}}panel.appendChild(detail);costDetail(detail,selectedCost);const done=rows.filter(x=>x.status==='completed'&&finite(x[metric])),failed=rows.length-done.length;add(panel,'p','axis-note','已完成 '+done.length+'／'+rows.length+' 格；未完成 '+failed+' 格。正差額 '+done.filter(x=>x[metric]>0).length+' 格，負差額 '+done.filter(x=>x[metric]<0).length+' 格。');if(failed)add(panel,'p','warning','研究有未完成成本情境；不要排除失敗格後宣稱整個範圍有利。');const brackets=[];for(const b of bs){for(let i=0;i<fs.length-1;i++){const a=rows.find(x=>x.financing_pct===fs[i]&&x.borrow_pct===b),z=rows.find(x=>x.financing_pct===fs[i+1]&&x.borrow_pct===b);if(a?.status==='completed'&&z?.status==='completed'&&a[metric]*z[metric]<0)brackets.push({borrow:rate(b),range:rate(fs[i])+' – '+rate(fs[i+1]),delta:signed(a[metric])+' → '+signed(z[metric])});}}if(brackets.length)table(panel,[['固定借券','borrow'],['融資翻號區間','range'],['已測差額','delta']],brackets);else add(panel,'p','axis-note','相鄰已完成點未找到翻號區間。未測利率可能仍有交點；不能外推為不存在損益兩平門檻。');add(panel,'p','axis-note','若找到翻號，只代表交點被兩個取樣點夾住，尚未解出精確利率；不跨失敗格搜尋。');select.addEventListener('change',()=>{metric=select.value;render(lastResult,false);$('sensitivity-metric').focus();});}
 function renderRisk(out,r){const {panel}=section(out,'財富之外，增加了多少風險？','以排除外部現金流的稅前、費前投資報酬計算。單一持倉／NAV 與總曝險為期間實際最大值，可能因價格漂移高於再平衡目標；ETF 按整個基金計算，未穿透成分股。這些指標不是風險調整 alpha 或未來上限。');const rows=comparisonRows(r).map(row=>{const risk=r.strategies?.[row.strategy]?.risk||{};return{...row,te:risk.tracking_error??row.tracking_error,vol:risk.volatility??row.volatility,dd:risk.max_drawdown??row.max_drawdown,concentration:risk.max_concentration??row.concentration,gross:risk.max_gross_exposure??row.max_gross_exposure};});table(panel,[['策略','label'],['年化追蹤誤差','te',pct],['年化波動','vol',pct],['最大回撤幅度',r=>finite(r.dd)?Math.abs(r.dd):null,pct],['最大單一持倉／NAV','concentration',pct],['最高總曝險',r=>finite(r.gross)?r.gross.toFixed(2)+'×':'—'],['維持比率清算','margin_liquidations',decimal]],rows);}
 function renderMC(out,r){const data=r.monte_carlo||{},rows=data.rows||[];if(!rows.length)return;const d=details(out,'額外情境路徑：模型條件下的分布',true);add(d,'p','explain','不同策略在每條路徑共用相同衝擊。路徑模型與 seed 決定這份分布；小樣本比例不是未來真實成功機率。');const done=rows.filter(x=>x.status==='completed'),s=data.summary||{};add(d,'p','axis-note','完成 '+done.length+'／'+rows.length+'；失敗 '+(rows.length-done.length)+'。D 相對 A 差額中位數 '+signed(s.median_delta)+'；第 5–95 百分位 '+signed(s.p05)+' 至 '+signed(s.p95)+'。');table(d,[['路徑',x=>x.path??x.path_id??x.sample_id],['狀態','status'],['D 財富','wealth_D',money],['D − A','delta_D_A',signed],['D − C','delta_D_C',signed],['失敗原因','error']],rows);}
 function renderDetails(out,r){const d=details(out,'逐年稅務、交易與批次紀錄');const select=add(d,'select','detail-select');select.id='ledger-strategy';Object.keys(labels).forEach(k=>{const o=add(select,'option','',labels[k]);o.value=k;});select.value='D';const body=add(d,'div');function ledger(){body.replaceChildren();const run=r.strategies?.[select.value]||{};add(body,'h4','subheading','年度資本稅與損失使用');table(body,[['年度','year'],['支付日期','payment_date'],['ST 收益','realized_st_gain',money],['LT 收益','realized_lt_gain',money],['ST 損失','realized_st_loss',money],['LT 損失','realized_lt_loss',money],['資本稅','tax',money],['ST 結轉','carry_st',money],['LT 結轉','carry_lt',money]],run.annual||[]);add(body,'h4','subheading','交易（顯示前 100 筆；完整資料在 ZIP）');table(body,[['日期','date'],['股票','ticker'],['方向','side'],['原因','reason'],['股數','shares',decimal],['價格','price',money],['費用','fee',money]],(run.trades||[]).slice(0,100));add(body,'h4','subheading','批次已實現損益（前 100 筆）');table(body,[['日期','date'],['股票','ticker'],['方向','side'],['批次','lot_id'],['股數','shares',decimal],['經濟損益','economic_pnl',money],['稅務損益','tax_pnl',money],['洗售遞延','wash_disallowed',money],['性質','character']],(run.realizations||[]).slice(0,100));}ledger();select.addEventListener('change',ledger);const decisions=r.strategies?.D?.optimizer_decisions||[];const q=details(out,'D 的最佳化決策與估計依據');add(q,'p','explain','固定多空方向，在當時可知的風險估計與局部正利得稅成本近似下選權重／交易。當期最佳化目標不等於終身稅後財富；完整帳本才計算實際稅款。');add(q,'p','axis-note','決策紀錄 '+decisions.length+' 筆；畫面顯示前 12 筆，完整內容隨 ZIP 保存。');add(q,'pre','',JSON.stringify(decisions.slice(0,12),null,2));const limits=details(out,'本次模型範圍與限制');const list=add(limits,'ul');(r.limitations||[]).forEach(x=>add(list,'li','',typeof x==='string'?x:JSON.stringify(x)));const provenance=details(out,'資料快照與程式版本');add(provenance,'pre','',JSON.stringify({run_id:r.run_id,data_kind:r.data_kind,data_label:r.data_label,data_metadata:r.data_metadata,engine_hashes:r.engine_hashes,optimization:r.request?.optimization,sensitivities:r.request?.sensitivities,monte_carlo:r.request?.monte_carlo},null,2));}
 function render(r,fresh=true){const out=$('output');out.replaceChildren();if(fresh)selectedCost=null;renderTop(out,r);renderCharts(out,r);renderSensitivity(out,r);renderRisk(out,r);renderMC(out,r);renderDetails(out,r);if(fresh){dirty=false;out.classList.remove('old-result');$('stale').hidden=true;$('export').disabled=false;$('print').disabled=false;}}
 function setBusy(value){busy=value;$('fields').disabled=value;$('run').disabled=value;$('reset').disabled=value;$('results').setAttribute('aria-busy',value?'true':'false');$('export').disabled=value||!lastResult||dirty;$('print').disabled=value||!lastResult||dirty;optionalFields();}
 $('lab-form').addEventListener('submit',async event=>{event.preventDefault();if(!defaults||busy)return;$('form-error').hidden=true;let request;try{if(!$('lab-form').reportValidity())return;request=await payload();}catch(e){$('form-error').textContent=e.message;$('form-error').hidden=false;$('status').textContent='請修正條件後再執行。';return;}setBusy(true);seconds=0;$('status').textContent='正在建立四策略、最佳化決策與完整清倉結果…';timer=window.setInterval(()=>{$('status').textContent='研究計算中 · 已經過 '+(++seconds)+' 秒。等待完整結果；這不是預估完成進度。';},1000);try{const response=await fetch('/api/tax-lab/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)});let r;try{r=await response.json();}catch(_){throw Error('伺服器未回傳有效 JSON，請查看執行視窗。');}if(!response.ok)throw Error(r.error||'研究未完成。');if(!r.strategies||!r.comparison||!r.run_id)throw Error('回應缺少四策略結果，已保留上次研究。');lastResult=r;render(r);$('status').textContent='四策略研究已完成。先看財富差，再檢查稅款、潛在負債與風險。';if(window.matchMedia('(max-width:850px)').matches)$('results').scrollIntoView({block:'start',behavior:'smooth'});}catch(e){$('form-error').textContent=e.message==='Failed to fetch'?'無法連線至預覽服務，請確認啟動程式仍在運作。':e.message;$('form-error').hidden=false;$('status').textContent=lastResult?'本次未完成，保留上次結果。請檢查錯誤後重算。':'本次未完成，請查看錯誤原因。';}finally{window.clearInterval(timer);setBusy(false);}});
 $('lab-form').addEventListener('input',markDirty);$('lab-form').addEventListener('change',markDirty);
 $('data-source').addEventListener('change',()=>{if(!defaults||busy)return;const group=sourceGroup();if(group!==activeGroup){drafts[activeGroup]=draft();applyGroup(baseConfig(),drafts[group]);activeGroup=group;}sourceNote();markDirty();});
 $('reset').addEventListener('click',reset);$('export').addEventListener('click',()=>{if(lastResult&&!dirty&&!busy)window.location.href='/api/tax-lab/download/'+encodeURIComponent(lastResult.run_id);});$('print').addEventListener('click',()=>{if(lastResult&&!dirty&&!busy)window.print();});
 fetch('/api/tax-lab/defaults').then(async response=>{if(!response.ok)throw Error('無法載入研究預設。');const d=await response.json();if(!d.demo_config||!d.observed_config)throw Error('缺少示例或歷史設定。');defaults=d;reset();setBusy(false);}).catch(e=>{$('boot-error').textContent=e.message+' 請確認使用獨立 Tax-Aware Lab 啟動程式。';$('boot-error').hidden=false;$('status').textContent='參數未載入，尚未開始計算。';});
})();
